#include "GameplayCombat3D.h"
#include <algorithm>

using namespace Aevrynd;
namespace GameplayLab {
void GameplayCombat3D::SpawnMonster(Vec3 position,float health){if(monsterCollider_)collision_.Destroy(monsterCollider_);if(monsterBody_)physics_.DestroyBody(monsterBody_);monster_={position,(std::max)(1.f,health),true};monsterCollider_=collision_.CreateBox({{position+Vec3{0,1,0},{.45f,1,.45f}},2,1,1,false});RigidBodySettings3D body{};body.type=RigidBodyType3D::Kinematic;body.transform.position=position+Vec3{0,1,0};body.colliderExtents={.45f,1,.45f};body.layer=2;body.collisionMask=1;monsterBody_=physics_.CreateBody(body);}
void GameplayCombat3D::BeginAttack(){attack_=nextAttack_;nextAttack_=attack_==Attack3D::Attack1?Attack3D::Attack2:attack_==Attack3D::Attack2?Attack3D::Attack3:Attack3D::Attack1;attackClock_=0;windowSwept_=false;hitThisAttack_.clear();}
void GameplayCombat3D::Sweep(const CombatInput3D& input){++stats_.sweeps;const Vec3 forward=Normalize(input.playerForward),center=input.playerPosition+Vec3{0,1,0}+forward*.7f;for(const auto handle:collision_.QueryBox(center,{1.8f,.9f,1.8f},{2,1,false})){if(!hitThisAttack_.insert(handle.value).second){++stats_.duplicateHits;continue;}const auto* collider=collision_.Get(handle);if(!collider||collider->userData!=1||!monster_.alive)continue;const float damage=attack_==Attack3D::Attack3?50.f:30.f;monster_.health=(std::max)(0.f,monster_.health-damage);++stats_.hits;if(monster_.health==0){monster_.alive=false;++stats_.kills;collision_.Destroy(monsterCollider_);physics_.DestroyBody(monsterBody_);monsterCollider_={};monsterBody_={};}}}
void GameplayCombat3D::Tick(const CombatInput3D& input,float deltaTime){deltaTime=Clamp(deltaTime,0,.1f);if(input.attackPressed&&(attack_==Attack3D::None||attackClock_>.42f))BeginAttack();if(attack_!=Attack3D::None){attackClock_+=deltaTime;if(!windowSwept_&&attackClock_>=.12f){Sweep(input);windowSwept_=true;}if(attackClock_>=.55f)attack_=Attack3D::None;}if(monster_.alive){aiClock_+=deltaTime;const Vec3 delta=input.playerPosition-monster_.position;const float distance=Length(delta);if(distance>1.4f&&distance<12.f){monster_.position=monster_.position+Normalize(delta)*deltaTime*1.8f;Transform3D transform{};transform.position=monster_.position+Vec3{0,1,0};physics_.SetTransform(monsterBody_,transform);collision_.UpdateBox(monsterCollider_,{{transform.position,{.45f,1,.45f}},2,1,1,false});}}}
}
